def validate(value,schema,path='study'):
 typ=schema.get('type')
 types={'object':dict,'array':list,'string':str}
 if typ in types: assert isinstance(value,types[typ]),(path,typ)
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  if 'items' in schema:
   for i,v in enumerate(value):validate(v,schema['items'],f'{path}[{i}]')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=value.keys(),path
  if schema.get('additionalProperties') is False:assert set(value)<=schema.get('properties',{}).keys(),path
  for k,v in value.items():
   if k in schema.get('properties',{}):validate(v,schema['properties'][k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert len(p['variants'])==4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==4
assert len({v['file'] for v in p['variants']})==4
normalized=[]
for v in p['variants']:
 f=Path(v['file']);assert f.name==str(f) and f.suffix=='.py'
 s=f.read_text();tree=ast.parse(s);compile(s,str(f),'exec')
 assert hashlib.sha256(s.encode()).hexdigest() in v['note']
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert cfg==v['config']
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): assert all(a.name.split('.')[0] in {'math','torch','unirank'} for a in node.names)
  if isinstance(node,ast.ImportFrom): assert node.module.split('.')[0] in {'math','torch','unirank'}
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name): assert node.func.id not in {'open','exec','eval','__import__'}
 tree.body=[n for n in tree.body if not (isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))]
 normalized.append(ast.dump(tree,include_attributes=False))
assert len(set(normalized))==1,'Arms differ beyond literal CONFIG'
assert {(v['config']['internal_match'],v['config']['terminal_match']) for v in p['variants']}=={(False,False),(False,True),(True,False),(True,True)}
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
print('PASS: study schema, evidence IDs, frozen protocol, four factorial cells, distinct standalone files, source hashes, literal configs, source compilation, arm equivalence outside CONFIG, import/IO boundaries, and unchanged baseline hash.')
print('NOT EXECUTED: torch import, tensor forward/backward, masking and numerical endpoint checks, GPU profiling, training or scoring. These remain host preflight requirements.')
print('proposal bytes',Path('proposal.json').stat().st_size)
